CREATE DATABASE IF NOT EXISTS nova_business CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nova_business;
CREATE TABLE IF NOT EXISTS settings (id INT AUTO_INCREMENT PRIMARY KEY, site_name VARCHAR(150) NOT NULL, logo VARCHAR(255), phone VARCHAR(40), whatsapp VARCHAR(40), email VARCHAR(150), hero_title VARCHAR(255), hero_text TEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
INSERT INTO settings(site_name,logo,phone,whatsapp,email,hero_title,hero_text) SELECT 'Nova Business','assets/logo.svg','+225 07 00 00 00 00','2250700000000','','Développez une activité qui vous ressemble.','Découvrez notre opportunité, nos produits et l’accompagnement proposé pour vous lancer sereinement.' WHERE NOT EXISTS (SELECT 1 FROM settings);
CREATE TABLE IF NOT EXISTS admins (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100), email VARCHAR(190) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, category VARCHAR(120), description TEXT, price DECIMAL(12,2) NULL, available TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_images (id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, image VARCHAR(255) NOT NULL, caption VARCHAR(255), sort_order INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS kits (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, description TEXT, price DECIMAL(12,2) NULL, content TEXT, image VARCHAR(255), available TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS trainings (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, description TEXT, content TEXT, published TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS testimonials (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, role VARCHAR(150), content TEXT NOT NULL, image VARCHAR(255), published TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS faqs (id INT AUTO_INCREMENT PRIMARY KEY, question VARCHAR(255) NOT NULL, answer TEXT NOT NULL, published TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS prospects (id INT AUTO_INCREMENT PRIMARY KEY, first_name VARCHAR(100), last_name VARCHAR(100), whatsapp VARCHAR(40), interest VARCHAR(100), message TEXT, source VARCHAR(100), status ENUM('Nouveau','Contacté','Intéressé','En suivi','Converti','Non intéressé') DEFAULT 'Nouveau', notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
